        dispose(owner,true);owner.Set("_model",model);owner.Set("_runtimes",runtimes);owner.Set("signature",signature);owner.Set("generation",owner.Get("generation").AsInt64()+1);owner.Get("_warnings").AsGodotArray().Clear();owner.Set("rate",30);owner.Set("origin",0.0);var ids=new Settings();var actors=model.Get("actors").AsGodotArray();foreach(var value in actors){var actor=value.As<Resource>();if(_settings.configured(actor))ids[actor.Get("id")]=true;}if(ids.Count==0){owner.Set("dirty",false);return;}var world=Module(owner,"world");world.Call("create");var prototypes=Map(owner,"prototypes");var geometryApi=GD.Load<GDScript>("res://scripts/actors/physics/physics_geometry.gd");
        foreach(var value in actors){var actor=value.As<Resource>();string id=actor.Get("id").AsString();if(!ids.ContainsKey(id))continue;var node=runtime(owner,id);var clip=model.Call("clip_for_actor_id",id).As<Resource>();if(node==null||clip==null||!node.Call("supports_remote_transform").AsBool())continue;if(Math.Abs(node.Call("remote_transform").AsTransform3D().Basis.Determinant())<.00000001){warn(owner,actor.Get("display_name").AsString()+": physics needs a nonzero scale on every axis.");continue;}var config=_settings.authored(actor);owner.Set("rate",Math.Max(owner.Get("rate").AsInt32(),Math.Clamp(config["steps"].AsInt32(),30,240)));double origin=Math.Min(owner.Get("origin").AsDouble(),clip.Get("start_time").AsDouble()-clip.Get("source_offset").AsDouble()/Math.Max(.001,clip.Get("playback_speed").AsDouble()));owner.Set("origin",origin);string type=actor.Get("type_id").AsString();int simulation=config["type"].AsInt32();var geometry=type is "powder" or "fluid"||simulation is 8 or 9?new Settings{["meshes"]=new GArray(),["points"]=Array.Empty<Vector3>(),["bounds"]=new Aabb(-Vector3.One*.5f,Vector3.One)}:geometryApi.Call("capture",node,ids).AsGodotDictionary();prototypes[id]=new Settings{["actor"]=actor,["clip"]=clip,["geometry"]=geometry,["graph"]=new Settings(),["graph_key"]="",["rope_node"]=default(Variant)};if(simulation==9)continue;double activation=clip.Get("start_time").AsDouble()+(config["activation"].AsDouble()-clip.Get("source_offset").AsDouble())/Math.Max(.001,clip.Get("playback_speed").AsDouble());var collision=owner.Call("_simulation_geometry",id,new Settings{["initial_time"]=activation,["initial_pose"]=animated_world(owner,id,activation,false,new Settings())}).AsGodotDictionary();var settings=config.Duplicate();if(config["shape"].AsInt32()==0&&type=="basic_shape")settings["shape"]=Get(Values(actor),"shape",0).AsInt32() switch{1=>2,2=>4,3=>3,_=>1};if(config["shape"].AsInt32()==6&&config["body_mode"].AsInt32()!=1&&!collision.ContainsKey("compound_points"))warn(owner,actor.Get("display_name").AsString()+": concave mesh collision is static-only; using a box.");var collider=geometryApi.Call("collider",collision,settings).AsGodotDictionary();string error=Get(collider,"error","").AsString();if(error.Length>0)warn(owner,actor.Get("display_name").AsString()+": "+error);if(collider.TryGetValue("compound",out var compound))world.Call("add_compound",id,compound,config["layer"],config["mask"]);else world.Call("add",id,collider["shape"],collider["offset"],config["layer"],config["mask"]);}
