        foreach(var id in prototypes.Keys){var prototype=prototypes[id].AsGodotDictionary();var actor=prototype["actor"].As<Resource>();var config=_settings.sample(actor,local(owner,actor,start));var clip=prototype["clip"].As<Resource>();if(!config["enabled"].AsBool()||start<clip.Get("start_time").AsDouble()-clip.Get("source_offset").AsDouble()/Math.Max(.001,clip.Get("playback_speed").AsDouble())-.000001||local(owner,actor,start)<config["activation"].AsDouble()-.000001||config["mode"].AsInt32()==0)continue;owner.Call("_initialize",id,states[id],config,start);states[id].AsGodotDictionary()["active"]=true;if(config["mode"].AsInt32()==3&&!is_baking(owner,id.AsString())){var frozen=config["frozen"].AsGodotDictionary();if(Get(frozen,"state").VariantType==Variant.Type.Dictionary)states[id]=snapshot(new Settings{[id]=frozen["state"]})[id];}if(config["mode"].AsInt32()==4&&!is_baking(owner,id.AsString())){var baked=owner.Call("_baked",config["bake"],start).AsGodotDictionary();if(baked.Count>0){baked["responds"]=false;states[id]=baked;}}}Module(owner,"destruction").Call("step",owner,start,0.0);Module(owner,"structure").Call("step",owner,start,0.0);Map(owner,"checkpoints")[0]=snapshot(states);owner.Set("_floor_step",-1);owner.Set("dirty",false);
